(()=>{const start=async()=>{let config=JSON.parse(document.getElementById('vtb-cloud-config')?.textContent||'{}');if(/^https?:$/.test(location.protocol)){const c=new AbortController(),t=setTimeout(()=>c.abort(),4000);try{const r=await fetch(new URL('site-config.json',document.baseURI),{cache:'no-store',signal:c.signal});if(r.ok)config=await r.json();}catch{}finally{clearTimeout(t)}}window.VTBCloudConfig=config;const load=src=>new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=reject;document.body.append(s)});try{await load('assets/supabase.9bc848903db15187.js');await load('assets/admin.15a30115554eab78.js');}catch{document.getElementById('vtb-start-status').textContent='Chưa tải được quản trị. Vui lòng kiểm tra mạng và tải lại trang.'}};start()})();